    TreeNode* curr = root;
    while (curr != nullptr) {
        if (curr->data > val && curr->left != nullptr) {
            curr = curr->left;
        } else if (curr->data < val && curr->right != nullptr) {
            curr = curr->right;
        } else break;
    }

    // If val is smaller, make it left 
    // child, else right child
    if (curr->data > val) {
        curr->left = temp;
    } else {
        curr->right = temp;
    }
    return root;
    }
};
